namespace AnalysisITC
{
	public partial class BindingAnalysisViewController : NSViewController
	{
        const float BaseContentWidth = 343;
        const float BaseContentHeight = 657;
        const float InformationLineHeight = 16;
        const float DefaultInformationHeight = 98;

        public static event EventHandler UpdateTable;

        private AnalysisResult Result { get; set; }
        bool preferredSizeUpdateQueued;
        NSLayoutConstraint informationLabelsHeightConstraint;
        NSLayoutConstraint informationValuesHeightConstraint;
        float informationAreaHeight = DefaultInformationHeight;

        public bool UseKelvin => TemperatureUnitControl.SelectedSegment == 1;

        public void SetResult(AnalysisResult result) => Result = result;

        public BindingAnalysisViewController (IntPtr handle) : base (handle)
		{
            
		}

        public override void ViewDidAppear()
        {
            base.ViewDidAppear();

            // Remove detach view button if alrady detached
            if (this.NextResponder is NSWindow window)
            {
                if (!window.IsSheet) DetachViewButton.Hidden = true;
            }

            Graph.Initialize(Result);

            Setup();
        }

        void Setup()
        {
            if (this.NextResponder is NSWindow) (this.NextResponder as NSWindow).Title = Result.Name;

            NameTextField.StringValue = Result.Name;
            CommentTextField.TextStorage.Replace(
                new NSRange(0, CommentTextField.TextStorage.Length),
                Result.Comments ?? string.Empty);

            var informationRows = new List<Tuple<string, string>>
            {
                Tuple.Create(
                    "Data sets",
                    Result.Solution.Solutions.Count + " experiment"
                    + (Result.Solution.Solutions.Count == 1 ? "" : "s")),
                Tuple.Create("Model", Result.Solution.SolutionName),
                Tuple.Create(
                    "Algorithm",
                    global::AnalysisITC.Core.Utilities.Extensions
                        .GetEnumDescription(Result.Solution.Convergence.Algorithm)),
                Tuple.Create(
                    "Iterations / RMSD / time",
                    Result.Solution.Convergence.Iterations
                    + " | " + Result.Solution.Loss.ToString("G3")
                    + " | " + Result.Solution.Convergence.Time
                        .TotalMilliseconds.ToString("F0") + " ms"),
            };

            if (Result.Solution.ErrorEstimationMethod == ErrorEstimationMethod.BootstrapResiduals)
            {
                informationRows.Add(Tuple.Create(
                    "Error estimation",
                    "Bootstrap residuals"));
                informationRows.Add(Tuple.Create(
                    "Bootstrap",
                    Result.Solution.BootstrapIterations + " iterations | "
                    + Result.Solution.BootstrapTime.TotalSeconds
                        .ToString("F1") + " s"));
            }
            else if (Result.Solution.ErrorEstimationMethod == ErrorEstimationMethod.ProfileLikelihood)
            {
                var profile = ProfileLikelihoodEstimator.Summarize(Result.Solution);
                informationRows.Add(Tuple.Create(
                    "Error estimation",
                    "Profile likelihood"));
                informationRows.Add(Tuple.Create(
                    "Profile status",
                    ProfileLikelihoodDisplayFormatter.Status(profile)));
                informationRows.Add(Tuple.Create(
                    "95% CI endpoints",
                    ProfileLikelihoodDisplayFormatter.Endpoints(profile)));
                informationRows.Add(Tuple.Create(
                    "Profile calculation time",
                    ProfileLikelihoodDisplayFormatter.Duration(profile)));
            }
            else if (Result.Solution.ErrorEstimationMethod == ErrorEstimationMethod.LeaveOneOut)
            {
                informationRows.Add(Tuple.Create(
                    "Error estimation",
                    "Leave-one-out"));
                informationRows.Add(Tuple.Create(
                    "Leave-one-out time",
                    Result.Solution.BootstrapTime.TotalSeconds
                        .ToString("F1") + " s"));
            }
            else
                informationRows.Add(Tuple.Create("Error estimation", "Not specified"));

            var cloneOptions = Result.Solution.ModelCloneOptions;
            informationRows.Add(Tuple.Create(
                "Weighted fitting",
                Result.Solution.UseWeightedFitting ? "Enabled" : "Off"));
            informationRows.Add(Tuple.Create(
                "Concentration uncertainty",
                cloneOptions == null
                    ? "Not specified"
                    : cloneOptions.HasLegacyCombinedLeaveOneOut
                        ? "Legacy combined leave-one-out"
                        : cloneOptions.IncludeConcentrationErrorsInBootstrap
                            ? "Included"
                            : "Not included"));
            informationRows.Add(Tuple.Create("Date", Result.UIShortDateWithTime));

            LabelLabel.StringValue = string.Join(
                Environment.NewLine,
                informationRows.Select(row => row.Item1 + ":"));
            FitParameterLabel.StringValue = string.Join(
                Environment.NewLine,
                informationRows.Select(row => row.Item2));
            ConfigureInformationArea(informationRows.Count);

            QueuePreferredContentSizeUpdate();
        }

        void ConfigureInformationArea(int rowCount)
        {
            informationAreaHeight = Math.Max(
                DefaultInformationHeight,
                rowCount * InformationLineHeight);

            LabelLabel.Cell.UsesSingleLineMode = false;
            FitParameterLabel.Cell.UsesSingleLineMode = false;

            if (informationLabelsHeightConstraint != null)
                informationLabelsHeightConstraint.Active = false;
            if (informationValuesHeightConstraint != null)
                informationValuesHeightConstraint.Active = false;
            informationLabelsHeightConstraint = LabelLabel.HeightAnchor
                .ConstraintEqualToConstant(informationAreaHeight);
            informationValuesHeightConstraint = FitParameterLabel.HeightAnchor
                .ConstraintEqualToConstant(informationAreaHeight);
            informationLabelsHeightConstraint.Active = true;
            informationValuesHeightConstraint.Active = true;
        }

        void QueuePreferredContentSizeUpdate()
        {
            if (preferredSizeUpdateQueued) return;

            preferredSizeUpdateQueued = true;
            BeginInvokeOnMainThread(() =>
            {
                preferredSizeUpdateQueued = false;
                View.NeedsLayout = true;
                View.LayoutSubtreeIfNeeded();

                var targetSize = new CGSize(
                    Math.Max(BaseContentWidth, View.Bounds.Width),
                    BaseContentHeight
                    + Math.Max(
                        0,
                        informationAreaHeight - DefaultInformationHeight));

                PreferredContentSize = targetSize;
                if (View.Window != null)
                {
                    var currentSize =
                        View.Window.ContentView?.Frame.Size
                        ?? new CGSize(0, 0);
                    if (Math.Abs(currentSize.Width - targetSize.Width) > 0.5
                        || Math.Abs(currentSize.Height - targetSize.Height) > 0.5)
                    {
                        View.Window.SetContentSize(targetSize);
                    }
                }
            });
        }

        partial void CopyToClipboard(NSObject sender)
        {
            Exporter.CopyToClipboard(
                Result,
                AppSettings.EnergyUnitFamily,
                null,
                UseKelvin);
        }

        partial void PopView(NSObject sender)
        {
            var storyboard = NSStoryboard.FromName("Main", null);
            var vc = storyboard.InstantiateControllerWithIdentifier("BindingAnalysisViewController")
                     as BindingAnalysisViewController;

            var wc = storyboard.InstantiateControllerWithIdentifier("DetachedAnalysisResultWindowController") as NSWindowController;

            (wc.ContentViewController as BindingAnalysisViewController).SetResult(Result);

            wc.ShowWindow(null);

            CloseButtonClicked(sender);
        }

        partial void LoadSolutionsToExperiments(NSObject sender)
        {
            StatusBarManager.SetStatus("Copying solutions to experiments...");

            foreach (var sol in Result.Solution.Solutions)
            {
                sol.Data.UpdateSolution(sol.Model);
            }

            StatusBarManager.ClearAppStatus();
            StatusBarManager.SetStatus("Solutions updated", 2000);

            DataAnalysisViewController.InvalidateGraph();
        }

        partial void CloseButtonClicked(NSObject sender)
        {
            if (this.NextResponder is NSWindow window)
            {
                if (window.IsSheet) DismissViewController(this);
                else window.Close();
            }
        }

        partial void EnableSolutionExperiments(NSObject sender)
        {
            var solutionexp = Result.Solution.Model.Models.Select(m => m.Data.UniqueID);

            DataManager.Data.ForEach(d => d.Include = solutionexp.Contains(d.UniqueID));

            DataManager.InvokeDataInclusionDidChange();
            UpdateTable?.Invoke(this, null);
        }

        partial void Apply(NSObject sender)
        {
            if (!string.IsNullOrWhiteSpace(NameTextField.StringValue))
                Result.Name = NameTextField.StringValue;

            Result.Comments = CommentTextField.String;

            CloseButtonClicked(sender);

            UpdateTable?.Invoke(this, null);
        }
    }
}
